data.query:
query Order($where: OrderWhereInput, $orderBy: [OrderOrderByInput!], $first: Int, $after: String) {
  order(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        businessPartner {
          id
          code
        }
        businessPartnerAddress {
          id
          code
        }
        orderType {
          id
          name
        }
        specialInstructions
      }
    }
  }
}

query Order($where: OrderWhereInput, $orderBy: [OrderOrderByInput!], $first: Int, $after: String) {
  order(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
       orderStatusId
        orderLines {
          edges {
            node {
              id
              number
              orderLineReleases {
                edges {
                  node {
                    id
                    number
                  }
                }
              }
            }
          }
        }
         businessPartner {
          id
          code
        }
        businessPartnerAddress {
          id
          code
        }
        orderType {
          id
          name
        }

        specialInstructions
      }
    }
  }
}

data.mutation:
mutation DeleteOrderCascade(
  $releasePayload: [OrderLineReleaseDeletePayloadInput!]!
  $linePayload: [OrderLineDeletePayloadInput!]!
  $orderPayload: [OrderDeletePayloadInput!]!
) {
  deleteOrderLineRelease(payload: $releasePayload) {
    id
  }
  deleteOrderLine(payload: $linePayload) {
    id
  }
  deleteOrder(payload: $orderPayload) {
    id
    number
  }
}

