}

data.variablesTransform:
(
  $update := $merge([
    {
      "quantity": { "value": quantity },
      "allowPartial": allowPartial,
      "dueAt": dueAt,
      "shipAt": shipAt
    },
    $exists(allowOverage) ? { "allowOverage": allowOverage} : {},
